def contract(role, foundation_task, foundation_deliverable, foundation_boundary,
             intermediate_task, intermediate_deliverable, intermediate_boundary, sources):
    if role in CONTRACTS:
        raise ValueError("Duplicate case contract: " + role)
    refs = [{"title": SOURCES[key][0], "url": SOURCES[key][1]} for key in sources.split()]
    CONTRACTS[role] = {
        "foundation": {"task": foundation_task, "deliverable": foundation_deliverable, "boundary": foundation_boundary},
        "intermediate": {"task": intermediate_task, "deliverable": intermediate_deliverable, "boundary": intermediate_boundary},
        "sources": refs,
    }


