def case_contract(role, level):
    if level not in ("foundation", "intermediate"):
        raise ValueError("Unsupported career case level")
    item = CONTRACTS[role]
    return {"title": CASE_TITLES[role], **deepcopy(item[level]), "sources": deepcopy(item["sources"])}
